def has = { String n -> binding.hasVariable(n) && binding.getVariable(n) != null }
def get = { String n -> has(n) ? binding.getVariable(n) : null }
def text = { String n -> def v = get(n); (v == null) ? '' : v.toString().trim() }
def action = text('action').toUpperCase()
def idIn = text('rateTableId')
def nm = text('name')
def modeIn = text('mode')
def tierIn = text('tiering')
def unitIn = text('unitType')
def desc = text('description')
def rawTags = get('tags')
def rawBands = get('bands')

def problems = []      // the request is malformed            -> INVALID_INPUT
def bandProblems = []  // the request is well-formed but wrong -> RATE_TABLE_INVALID
def ACTIONS = ['GET', 'CREATE', 'UPDATE'] as Set
if (!ACTIONS.contains(action)) problems << ('action must be GET, CREATE or UPDATE, got "' + text('action') + '"')
boolean isWrite = (action == 'CREATE' || action == 'UPDATE')
if ((action == 'GET' || action == 'UPDATE') && idIn.isEmpty()) problems << ('rateTableId is required for ' + action)

String mode = 'Rate'
String tiering = 'Marginal'
String unitType = 'Percent'
def tags = []
if (isWrite) {
    if (nm.isEmpty()) problems << 'name is required'
    else if (nm.length() > 120) problems << 'name must be 120 characters or fewer'
    if (!modeIn.isEmpty()) { def m = ['Rate', 'PctOfTarget'].find { it.equalsIgnoreCase(modeIn) }; if (m == null) problems << ('mode must be Rate or PctOfTarget, got "' + modeIn + '"'); else mode = m }
    if (!tierIn.isEmpty()) { def t = ['Marginal', 'Cliff'].find { it.equalsIgnoreCase(tierIn) }; if (t == null) problems << ('tiering must be Marginal or Cliff, got "' + tierIn + '"'); else tiering = t }
    if (!unitIn.isEmpty()) { def u = ['Percent', 'Amount', 'Quantity'].find { it.equalsIgnoreCase(unitIn) }; if (u == null) problems << ('unitType must be Percent, Amount or Quantity, got "' + unitIn + '"'); else unitType = u }
    if (desc.length() > 2000) problems << 'description must be 2000 characters or fewer'
    // Tags arrive as a list (the app), a JSON list or a comma-separated string (API callers).
    def tagsIn = rawTags
    if (tagsIn instanceof String) {
        def t = tagsIn.trim()
        if (t.isEmpty()) tagsIn = []
        else if (t.startsWith('[')) { try { tagsIn = new groovy.json.JsonSlurper().parseText(t) } catch (Exception e) { problems << ('tags is not valid JSON: ' + e.getMessage()); tagsIn = [] } }
        else tagsIn = t.split(',') as List
    }
    if (tagsIn == null) tagsIn = []
    if (!(tagsIn instanceof List)) { problems << 'tags must be a list of strings'; tagsIn = [] }
    def seen = [] as HashSet
    tagsIn.each { v ->
        def s = (v == null) ? '' : v.toString().trim()
        if (s.isEmpty()) return
        if (s.length() > 40) { problems << ('tag "' + s.take(40) + '..." is longer than 40 characters'); return }
        if (seen.add(s.toLowerCase())) tags << s
    }
    if (tags.size() > 20) problems << 'a rate table may have at most 20 tags'
}

long OPEN = 2147483647L
def bandsIn = rawBands
if (bandsIn instanceof String) {
    def t = bandsIn.trim()
    if (t.isEmpty()) bandsIn = null
    else { try { bandsIn = new groovy.json.JsonSlurper().parseText(t) } catch (Exception e) { problems << ('bands is not valid JSON: ' + e.getMessage()); bandsIn = null } }
}
if (bandsIn instanceof Map) bandsIn = [bandsIn]
def bands = []
if (isWrite) {
    if (!(bandsIn instanceof List) || bandsIn.isEmpty()) bandProblems << 'a rate table needs at least one band'
    else if (bandsIn.size() > 50) bandProblems << 'a rate table may have at most 50 bands'
    else {
        def toBps = { v, String where ->
            if (v == null) return null
            if (v instanceof Number) { double d = ((Number) v).doubleValue(); if (d != Math.rint(d)) { bandProblems << (where + ' must be a whole number of basis points'); return null }; return ((Number) v).longValue() }
            def t = v.toString().trim()
            if (t.isEmpty()) return null
            if (t ==~ /^-?\d{1,10}$/) return Long.parseLong(t)
            bandProblems << (where + ' must be a whole number of basis points, got "' + t + '"'); return null
        }
        int n = bandsIn.size()
        bandsIn.eachWithIndex { b, i ->
            def where = 'band ' + (i + 1)
            if (!(b instanceof Map)) { bandProblems << (where + ' must be an object'); return }
            Long from = toBps(b.fromPct, where + '.fromPct')
            Long to = toBps(b.toPct, where + '.toPct')
            Long val = toBps(b.value, where + '.value')
            String label = (b.label == null) ? '' : b.label.toString().trim()
            boolean last = (i == n - 1)
            if (from == null) bandProblems << (where + '.fromPct is required')
            if (to == null) { if (last) to = OPEN; else bandProblems << (where + '.toPct is required on every band but the last') }
            if (val == null) bandProblems << (where + '.value is required')
            if (from != null && from < 0L) bandProblems << (where + '.fromPct cannot be negative')
            if (val != null && val < 0L) bandProblems << (where + '.value cannot be negative')
            if (val != null && val > OPEN) bandProblems << (where + '.value is out of range')
            if (to != null && to > OPEN) bandProblems << (where + '.toPct is out of range')
            if (from != null && to != null && to != OPEN && to <= from) bandProblems << (where + ': toPct must be greater than fromPct')
            if (label.length() > 60) bandProblems << (where + '.label must be 60 characters or fewer')
            bands << [fromPct: from, toPct: to, value: val, label: label]
        }
        if (bandProblems.isEmpty()) {
            bands = bands.sort { a, b -> Long.compare(a.fromPct, b.fromPct) }
            if (bands[0].fromPct != 0L) bandProblems << 'the first band must start at 0 (0%), so every attainment lands on a band'
            for (int i = 1; i < bands.size(); i++) {
                def prev = bands[i - 1]; def cur = bands[i]
                if (prev.toPct == OPEN) bandProblems << ('band ' + i + ' is open-ended, so no band can follow it')
                else if (cur.fromPct < prev.toPct) bandProblems << ('band ' + (i + 1) + ' overlaps band ' + i + ' (starts at ' + cur.fromPct + ', before ' + prev.toPct + ')')
                else if (cur.fromPct > prev.toPct) bandProblems << ('gap between band ' + i + ' and band ' + (i + 1) + ' (' + prev.toPct + ' to ' + cur.fromPct + '): attainment there would earn nothing')
            }
        }
    }
}

// CREATE mints the business id; a collision is checked downstream rather than assumed away.
String newId = 'RT-' + UUID.randomUUID().toString().replace('-', '').substring(0, 8).toUpperCase()
String targetId = (action == 'CREATE') ? newId : idIn
def targetFilter = [operator: 'AND', filters: [[property: 'properties.rateTableId', filter: [operator: 'EQUAL', value: targetId.isEmpty() ? '__none__' : targetId]]]]
// The name check reads EVERY table and compares in n_Guard. A CONTAINS/ICONTAINS
// filter is routed to the analytics index on this object, which lags the store by
// seconds - long enough for a just-created table to be missed. An unfiltered read hits
// the primary store; the set is small reference data and the read is bounded.
def nameFilter = isWrite && !nm.isEmpty()
    ? [:]
    : [operator: 'AND', filters: [[property: 'id', filter: [operator: 'EQUAL', value: '__none__']]]]

return [valid: problems.isEmpty(), reason: problems.join('; '),
        bandsValid: bandProblems.isEmpty(), bandsReason: bandProblems.join('; '),
        action: action, isGet: (action == 'GET'), targetId: targetId, name: nm, mode: mode, tiering: tiering,
        unitType: unitType, description: desc, tags: tags,
        bands: bands, bandCount: bands.size(), targetFilter: targetFilter, nameFilter: nameFilter]

def existing = (byIdRows != null && !byIdRows.isEmpty()) ? byIdRows[0] : null
boolean notFound = (String.valueOf(action) != 'CREATE') && existing == null
boolean collision = (String.valueOf(action) == 'CREATE') && existing != null
String recordId = (existing == null) ? '' : String.valueOf(existing.id)
boolean dup = false
String dupId = ''
if (String.valueOf(action) == 'CREATE' || String.valueOf(action) == 'UPDATE') {
    (byNameRows ?: []).each { r ->
        def n = String.valueOf(r.properties?.name ?: '')
        // Equality here is case-insensitive and exact, and a table may of course keep its
        // own name on UPDATE.
        if (n.equalsIgnoreCase(String.valueOf(name)) && String.valueOf(r.id) != recordId) { dup = true; dupId = String.valueOf(r.properties?.rateTableId ?: '') }
    }
}
int nameGot = (byNameRows == null) ? 0 : byNameRows.size()
int nameTotal = (byNameTotal == null || String.valueOf(byNameTotal).trim().isEmpty()) ? nameGot : Integer.valueOf(String.valueOf(byNameTotal))
boolean nameCheckTruncated = nameGot < nameTotal
def bandFilter = [operator: 'AND', filters: [[property: 'properties.rateTableId', filter: [operator: 'IN', value: [recordId.isEmpty() ? '__none__' : recordId]]]]]
def ex = (existing == null) ? [:] : (existing.properties ?: [:])
// Numbers a table may not have yet (created before v3) come out as 0, never null:
// a null is dropped from the output and reaches the next node unbound.
def asLong0 = { v -> (v == null || String.valueOf(v).trim().isEmpty()) ? 0L : Long.valueOf(String.valueOf(v)) }
return [notFound: notFound, collision: collision, recordId: recordId, isDup: dup, dupId: dupId, nameCheckTruncated: nameCheckTruncated, bandFilter: bandFilter,
        existingName: String.valueOf(ex.name ?: ''), existingMode: String.valueOf(ex.mode ?: ''), existingTiering: String.valueOf(ex.tiering ?: ''),
        existingDescription: String.valueOf(ex.description ?: ''), existingTags: (ex.tags instanceof List) ? ex.tags : [], existingUnitType: String.valueOf(ex.unitType ?: ''),
        existingVersion: asLong0(ex.version), existingEffectiveStart: asLong0(ex.effectiveStart), existingEffectiveEnd: asLong0(ex.effectiveEnd)]

long OPEN = 2147483647L
def asLong = { v -> (v == null || String.valueOf(v).trim().isEmpty()) ? null : Long.valueOf(String.valueOf(v)) }
// Record ids are minted from the business id, so CREATE and UPDATE write the same rows
// and a retry after a half-landed write lands on the same records instead of beside them.
def md5hex = { String s -> java.security.MessageDigest.getInstance('MD5').digest(s.getBytes('UTF-8')).encodeHex().toString() }
def mint = { String seed -> 'e_' + md5hex(seed).substring(0, 24) }

String act = String.valueOf(action)
boolean isGet = (act == 'GET')
boolean ok = (valid as boolean)
String outcome
String refusal = ''
if (!ok) { outcome = 'INVALID_INPUT'; refusal = String.valueOf(reason) }
else if (collision as boolean) { outcome = 'INVALID_INPUT'; refusal = 'The minted rateTableId collided with an existing table; retry the request.' }
else if (notFound as boolean) { outcome = 'NOT_FOUND'; refusal = 'No rate table has rateTableId "' + String.valueOf(targetId) + '"' }
else if (isGet) { outcome = 'OK' }
else if (nameCheckTruncated as boolean) { outcome = 'INVALID_INPUT'; refusal = 'Could not verify the name is unique: more rate tables exist than one read returns. Narrow the set before creating more.' }
else if (isDup as boolean) { outcome = 'DUPLICATE_NAME'; refusal = 'A rate table named "' + String.valueOf(name) + '" already exists (' + String.valueOf(dupId) + ')' }
else if (!(bandsValid as boolean)) { outcome = 'RATE_TABLE_INVALID'; refusal = String.valueOf(bandsReason) }
else { outcome = 'WRITE' }

String parentId = (act == 'CREATE') ? mint('RateTable#' + String.valueOf(targetId)) : String.valueOf(recordId)
def sortedExisting = (existingBands ?: []).collect { r -> [id: String.valueOf(r.id), bandId: String.valueOf(r.properties?.bandId ?: ''), label: String.valueOf(r.properties?.label ?: ''),
        fromPct: asLong(r.properties?.fromPct), toPct: asLong(r.properties?.toPct), value: asLong(r.properties?.value)] }
    .sort { a, b -> Long.compare(a.fromPct == null ? 0L : a.fromPct, b.fromPct == null ? 0L : b.fromPct) }

// Version info. P0 has one version per table: 1, effective from the day it was created,
// open-ended (effectiveEnd 0 = End of Time). UPDATE keeps what is there and backfills a
// table written before these fields existed.
long today = java.time.LocalDate.now(java.time.ZoneOffset.UTC).atStartOfDay(java.time.ZoneOffset.UTC).toInstant().toEpochMilli()
long exVersion = asLong(existingVersion) ?: 0L
long exStart = asLong(existingEffectiveStart) ?: 0L
long exEnd = asLong(existingEffectiveEnd) ?: 0L
long outVersion = (act == 'CREATE') ? 1L : (exVersion > 0L ? exVersion : 1L)
long outStart = (act == 'CREATE') ? today : (exStart > 0L ? exStart : (isGet ? 0L : today))
long outEnd = exEnd
String exUnit = String.valueOf(existingUnitType ?: '')
def exTags = (existingTags instanceof List) ? existingTags : []
def newTags = (tags instanceof List) ? tags : []

def outBands = []
def updates = []
def deleteIds = []
if (outcome == 'OK') {
    sortedExisting.each { b -> outBands << [id: b.id, bandId: b.bandId, label: b.label, fromPct: b.fromPct ?: 0L, toPct: b.toPct ?: 0L, value: b.value ?: 0L, openEnded: (b.toPct == OPEN)] }
} else if (outcome == 'WRITE') {
    def set = { String f, v -> [fieldName: 'properties.' + f, actionType: 'SET', setValue: v] }
    def parentFields = [set('rateTableId', String.valueOf(targetId)), set('name', String.valueOf(name)), set('mode', String.valueOf(mode)), set('tiering', String.valueOf(tiering)),
                        set('unitType', String.valueOf(unitType)), set('description', String.valueOf(description)), set('tags', newTags)]
    if (act == 'CREATE' || exVersion <= 0L) parentFields << set('version', outVersion)
    if (act == 'CREATE' || exStart <= 0L) parentFields << set('effectiveStart', outStart)
    updates << [id: parentId, updateFields: parentFields]
    def keep = [] as HashSet
    (bands ?: []).eachWithIndex { b, i ->
        int n = i + 1
        String bandId = String.valueOf(targetId) + '-B' + n
        String bid = mint('RateTableBand#' + String.valueOf(targetId) + '#' + n)
        keep << bid
        long from = asLong(b.fromPct); long to = asLong(b.toPct); long val = asLong(b.value)
        outBands << [id: bid, bandId: bandId, label: String.valueOf(b.label ?: ''), fromPct: from, toPct: to, value: val, openEnded: (to == OPEN)]
    }
    // The parent row goes first so its FK target exists before any band names it.
    outBands.each { b -> updates << [id: b.id, updateFields: [set('bandId', b.bandId), set('rateTableId', parentId), set('label', b.label), set('fromPct', b.fromPct), set('toPct', b.toPct), set('value', b.value)]] }
    sortedExisting.each { b -> if (!keep.contains(b.id)) deleteIds << b.id }
}
def deleteFilter = [operator: 'AND', filters: [[property: 'id', filter: [operator: 'IN', value: deleteIds.isEmpty() ? ['__none__'] : deleteIds]]]]
def parentUpdates = updates.isEmpty() ? [] : [updates[0]]
def bandUpdates = updates.size() > 1 ? new ArrayList(updates.subList(1, updates.size())) : []

return [outcome: outcome, refusal: refusal, parentId: parentId,
        parentUpdates: parentUpdates, bandUpdates: bandUpdates, bandWriteCount: bandUpdates.size(),
        deleteIds: deleteIds, deleteCount: deleteIds.size(), deleteFilter: deleteFilter,
        bands: outBands, bandCount: outBands.size(),
        outName: isGet ? String.valueOf(existingName) : String.valueOf(name),
        outMode: isGet ? String.valueOf(existingMode) : String.valueOf(mode),
        outTiering: isGet ? String.valueOf(existingTiering) : String.valueOf(tiering),
        outUnitType: isGet ? (exUnit.isEmpty() ? 'Percent' : exUnit) : String.valueOf(unitType),
        outDescription: isGet ? String.valueOf(existingDescription) : String.valueOf(description),
        outTags: isGet ? exTags : newTags,
        outVersion: isGet ? (exVersion > 0L ? exVersion : 1L) : outVersion,
        outEffectiveStart: outStart, outEffectiveEnd: outEnd,
        message: (outcome == 'OK') ? ('Rate table ' + String.valueOf(targetId) + ' with ' + outBands.size() + ' band(s)') : refusal]

def has = { String n -> binding.hasVariable(n) && binding.getVariable(n) != null }
def get = { String n -> has(n) ? binding.getVariable(n) : null }
def text = { String n -> def v = get(n); (v == null) ? '' : v.toString().trim() }
def num = { String n -> def v = get(n); (v == null || v.toString().trim().isEmpty()) ? -1L : Long.valueOf(String.valueOf(v)) }
long okT = num('okT'), badT = num('badT'), okB = num('okB'), badB = num('badB')
long wantB = num('bandWriteCount'), wantDel = num('deleteCount'), gotDel = num('deleted')
if (okT < 0L) okT = 0L
if (badT < 0L) badT = 0L
if (okB < 0L) okB = 0L
if (badB < 0L) badB = 0L
def problems = []
if (okT != 1L || badT > 0L) problems << ('the rate table row: ' + okT + ' written, ' + badT + ' failed' + (has('errT') && get('errT') != null ? (' - ' + get('errT').toString().take(240)) : ''))
if (okB != wantB || badB > 0L) problems << ('the bands: ' + okB + ' of ' + wantB + ' written, ' + badB + ' failed' + (has('errB') && get('errB') != null ? (' - ' + get('errB').toString().take(240)) : ''))
// An unverifiable delete is reported, never assumed: a surplus band left behind would
// silently widen the table.
if (wantDel > 0L && gotDel != wantDel) problems << ('surplus bands: ' + (gotDel < 0L ? 'could not verify the delete count' : (gotDel + ' of ' + wantDel + ' removed')))
boolean partial = !problems.isEmpty()
String act = text('action')
String status = partial ? 'PARTIAL_WRITE' : (act == 'CREATE' ? 'CREATED' : 'UPDATED')
String message = partial
    ? ('The write did not fully land - ' + problems.join('; ') + '. Retry with action UPDATE and the same rateTableId: the write is idempotent.')
    : (act == 'CREATE' ? 'Rate table created' : 'Rate table updated')
return [partial: partial, status: status, message: message, written: okT + okB, deleted: (gotDel < 0L ? 0L : gotDel)]
